using System;using System.Security.Cryptography;using System.Text;using System.Collections.Concurrent;
namespace SoulboundLegends.NetworkTransport;
public interface IAuthenticationValidator{bool Validate(string authToken,ReadOnlySpan<byte> proof,ulong connectionId,ReadOnlySpan<byte> clientNonce,ReadOnlySpan<byte> serverNonce);}
public sealed class SharedSecretAuthenticationValidator:IAuthenticationValidator{readonly byte[] secret;public SharedSecretAuthenticationValidator(string s){secret=Encoding.UTF8.GetBytes(s??"");}public bool Validate(string token,ReadOnlySpan<byte> proof,ulong id,ReadOnlySpan<byte> clientNonce,ReadOnlySpan<byte> serverNonce){if(secret.Length==0||string.IsNullOrEmpty(token)||proof.Length!=32)return false;using var h=new HMACSHA256(secret);using var m=new System.IO.MemoryStream();m.Write(clientNonce);m.Write(serverNonce);m.Write(BitConverter.GetBytes(id));m.Write(Encoding.UTF8.GetBytes(token));var expected=h.ComputeHash(m.ToArray());return CryptographicOperations.FixedTimeEquals(expected,proof);}}
public sealed class NonceReplayGuard{readonly ConcurrentDictionary<string,long> seen=new();readonly TimeSpan ttl;public NonceReplayGuard(TimeSpan t){ttl=t;}public bool TryUse(byte[] nonce){var k=Convert.ToBase64String(nonce);var now=DateTime.UtcNow.Ticks;seen[k]=now;foreach(var x in seen)if(now-x.Value>ttl.Ticks)seen.TryRemove(x.Key,out _);return true;}}
public sealed class RateLimiter{readonly int maxMessages,maxBytes;int messages,bytes;long window=Environment.TickCount64;public RateLimiter(int m,int b){maxMessages=m;maxBytes=b;}public bool Allow(int n){var now=Environment.TickCount64;if(now-window>=1000){window=now;messages=bytes=0;}if(messages+1>maxMessages||bytes+n>maxBytes)return false;messages++;bytes+=n;return true;}}
